<?php
declare(strict_types=1);
$ndAlerts=org_sales_notifications($dbh,$orgId);$ndEvents=[];try{$ndEvents=org_sales_commerce_event_feed($dbh,$orgId,20);}catch(Throwable $e){}$ndCount=count($ndAlerts)+count($ndEvents);$ndUnread=min($ndCount,5);
$ndItems=[];foreach($ndAlerts as $a){$ndItems[]=['title'=>(string)($a['type']??'Store alert'),'copy'=>(string)($a['message']??''),'icon'=>'fa-exclamation-triangle','tone'=>'orange','time'=>'Now','href'=>(string)($a['action']??'#')];}foreach($ndEvents as $e){$type=(string)($e['type']??'Store activity');$ndItems[]=['title'=>ucwords($type),'copy'=>(string)($e['message']??$e['description']??'Store activity updated.'),'icon'=>stripos($type,'order')!==false?'fa-shopping-cart':'fa-bell-o','tone'=>'blue','time'=>(string)($e['created_at']??'Recent'),'href'=>'#'];}if(!$ndItems){$ndItems=[['title'=>'Welcome to notifications','copy'=>'Important store alerts and activities will appear here.','icon'=>'fa-bell-o','tone'=>'blue','time'=>'Now','href'=>'#']];}
