h:27px;height:27px;border-radius:6px;background:#eef3ff;color:#143dff;display:grid;place-items:center;font-size:12px}.nd-pref span{flex:1}.nd-pref small{display:block;color:var(--m)}.nd-on,.nd-off{font-size:7px;border-radius:999px;padding:3px 7px;background:#dcfce7;color:#15803d}.nd-off{background:#eef2f7;color:#64748b}.nd-summary{display:grid;grid-template-columns:repeat(4,1fr);gap:6px}.nd-sum{border:1px solid var(--b);border-radius:6px;text-align:center;padding:7px 3px;font-size:7px}.nd-sum i{font-size:13px;color:#143dff}.nd-sum strong{display:block;font-size:12px;margin:4px 0}.nd-activity{display:flex;justify-content:space-between;padding:7px 0;border-bottom:1px solid var(--b);font-size:7px}@media(max-width:900px){.nd{height:auto;overflow:visible}.nd-grid{grid-template-columns:1fr}.nd-side{grid-template-rows:auto}}</style>
<main class="nd"><header class="nd-head"><div><p class="nd-crumb">Home › Notifications</p><h1>Notifications</h1><p class="nd-sub">Stay updated with important alerts and activities in your store.</p></div><button class="nd-read" id="ndRead">Mark all as read</button></header><div class="nd-grid"><section class="nd-card"><div class="nd-tabs"><span>All <b><?=$ndCount?></b></span><span>Unread <b id="ndUnread"><?=$ndUnread?></b></span><span>Orders</span><span>Products</span><span>Customers</span><span>System</span></div><div class="nd-list"><?php foreach(array_slice($ndItems,0,8) as $n):?><a class="nd-item" href="<?=h($n['href'])?>"><i class="fa <?=$n['icon']?> nd-icon <?=$n['tone']?>"></i><div><strong><?=h($n['title'])?></strong><p><?=h($n['copy'])?></p></div><span class="nd-time"><?=h($n['time'])?></span></a><?php endforeach;?></div><div class="nd-pages">‹ &nbsp; <b>1</b> &nbsp; 2 &nbsp; 3 &nbsp; ›</div></section><aside class="nd-side"><section class="nd-card nd-box"><h2>Notification Preferences</h2><p>Manage how you receive notifications.</p><?php foreach([['fa-envelope-o','Email Notifications','Receive emails for important updates',1],['fa-bell-o','In-App Notifications','Show notifications in the system',1],['fa-commenting-o','SMS Notifications','Receive SMS for critical alerts',0],['fa-mobile','Push Notifications','Receive push notifications on mobile',1]] as $p):?><div class="nd-pref"><i class="fa <?=$p[0]?>"></i><span><strong><?=$p[1]?></strong><small><?=$p[2]?></small></span><b class="<?=$p[3]?'nd-on':'nd-off'?>"><?=$p[3]?'On':'Off'?></b></div><?php endforeach;?></section><section class="nd-card nd-box"><h2>Notification Summary</h2><p>Overview of your notifications</p><div class="nd-summary"><?php foreach([['fa-envelope-o',12,'Email'],['fa-bell-o',$ndCount,'In-App'],['fa-commenting-o',2,'SMS'],['fa-mobile',6,'Push']] as $s):?><div class="nd-sum"><i class="fa <?=$s[0]?>"></i><strong><?=$s[1]?></strong><?=$s[2]?></div><?php endforeach;?></div></section><section class="nd-card nd-box"><h2>Recent Activity</h2><?php foreach(array_slice($ndItems,0,4) as $n):?><div class="nd-activity"><span><?=h($n['title'])?></span><small><?=h($n['time'])?></small></div><?php endforeach;?></section></aside></div></main><script>document.getElementById('ndRead')?.addEventListener('click',function(){document.getElementById('ndUnread').textContent='0';this.textContent='All read'});</script>
